declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/document_manager.php';require __DIR__.'/includes/project_manager.php';require_permission('projects.view');$pdo=db();$id=(int)($_GET['id']??0);$p=pm_fetch_project($pdo,$id);pm_recalculate_project($pdo,$id);$p=pm_fetch_project($pdo,$id);$pageTitle=$p['name'];
$mil=$pdo->prepare("SELECT m.*,(SELECT COUNT(*) FROM project_tasks t WHERE t.milestone_id=m.id) task_count,(SELECT COUNT(*) FROM project_tasks t WHERE t.milestone_id=m.id AND t.status='done') done_count FROM project_milestones m WHERE m.project_id=? ORDER BY sort_order,due_date,id");$mil->execute([$id]);$milestones=$mil->fetchAll();$ts=$pdo->prepare("SELECT t.*,u.name assigned_name,m.name milestone_name,(SELECT COALESCE(SUM(hours),0) FROM project_time_entries te WHERE te.task_id=t.id) actual_hours FROM project_tasks t LEFT JOIN users u ON u.id=t.assigned_to LEFT JOIN project_milestones m ON m.id=t.milestone_id WHERE t.project_id=? ORDER BY t.status='done',t.due_date IS NULL,t.due_date,t.sort_order LIMIT 12");$ts->execute([$id]);$tasks=$ts->fetchAll();$members=$pdo->prepare("SELECT pm.*,u.name,u.avatar_path FROM project_members pm JOIN users u ON u.id=pm.user_id WHERE pm.project_id=? ORDER BY pm.role_name,u.name");$members->execute([$id]);$members=$members->fetchAll();$time=$pdo->prepare('SELECT COALESCE(SUM(hours),0) FROM project_time_entries WHERE project_id=?');$time->execute([$id]);$hours=(float)$time->fetchColumn();$exp=$pdo->prepare('SELECT COALESCE(SUM(amount),0) FROM project_expenses WHERE project_id=? AND currency=?');$exp->execute([$id,$p['currency']]);$expenses=(float)$exp->fetchColumn();$ris=$pdo->prepare("SELECT COUNT(*) FROM project_risks WHERE project_id=? AND status IN ('open','mitigating')");$ris->execute([$id]);$openRisks=(int)$ris->fetchColumn();$fq=$pdo->prepare("SELECT pf.*,u.name user_name FROM project_files pf LEFT JOIN users u ON u.id=pf.uploaded_by WHERE pf.project_id=? ORDER BY pf.created_at DESC LIMIT 20");$fq->execute([$id]);$files=$fq->fetchAll();require __DIR__.'/includes/header.php';echo pm_project_tabs($id,'summary');?>
<div class="project-hero" style="--project-color:<?=e($p['color'])?>"><div><span class="eyebrow"><?=e($p['code']?:'PROYECTO')?> · <?=e($p['company_name']?:'INTERNO')?></span><h2><?=e($p['name'])?></h2><p><?=e($p['description']?:'Sin descripción del alcance todavía.')?></p><div class="project-badges"><?=pm_badge($p['status'])?> <?=pm_badge($p['health'],'health')?> <?=pm_badge($p['priority'],'priority')?></div></div><div class="actions"><?php if(has_permission('project_tasks.manage')):?><a class="btn btn-primary" href="project_task_form.php?project_id=<?=$id?>">+ TAREA</a><?php endif;?><?php if(has_permission('projects.manage')):?><a class="btn btn-secondary" href="project_form.php?id=<?=$id?>">EDITAR PROYECTO</a><?php endif;?></div></div>
<div class="pm-kpis"><div class="stat-card"><small>AVANCE</small><strong><?=(int)$p['progress']?>%</strong><div class="pm-progress"><span style="width:<?=(int)$p['progress']?>%"></span></div></div><div class="stat-card"><small>FECHA ENTREGA</small><strong><?=e(pm_date($p['due_date']))?></strong><span>Inicio <?=e(pm_date($p['start_date']))?></span></div><div class="stat-card"><small>HORAS REGISTRADAS</small><strong><?=e(number_format($hours,1,',','.'))?></strong><span>Tarifa <?=e(format_money($p['hourly_rate'],$p['currency']))?></span></div><div class="stat-card"><small>PRESUPUESTO</small><strong><?=e(format_money($p['budget'],$p['currency']))?></strong><span>Gastos <?=e(format_money($expenses,$p['currency']))?></span></div><div class="stat-card <?=$openRisks?'danger':''?>"><small>RIESGOS ABIERTOS</small><strong><?=$openRisks?></strong><span>Monitoreo activo</span></div></div>
<div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><h2>Hitos</h2><span class="table-sub">Entregables y puntos de control.</span></div><?php if(has_permission('projects.manage')):?><a class="btn btn-light btn-small" href="project_milestone_form.php?project_id=<?=$id?>">+ Hito</a><?php endif;?></div><div class="panel-body pm-milestones"><?php if(!$milestones):?><div class="empty">Aún no hay hitos.</div><?php endif;?><?php foreach($milestones as$m):$pct=$m['task_count']?(int)round($m['done_count']/$m['task_count']*100):($m['status']==='completed'?100:0);?><article><div><strong><?=e($m['name'])?></strong><small><?=e(pm_date($m['due_date']))?> · <?=$m['done_count']?>/<?=$m['task_count']?> tareas</small></div><div class="pm-progress"><span style="width:<?=$pct?>%"></span></div></article><?php endforeach;?></div></section><aside><section class="panel"><div class="panel-header"><div><h2>Equipo</h2><span class="table-sub">Responsables y asignación.</span></div><?php if(has_permission('projects.manage')):?><a class="btn btn-light btn-small" href="project_members.php?project_id=<?=$id?>">Gestionar</a><?php endif;?></div><div class="panel-body pm-member-list"><?php if(!$members):?><div class="empty">Sin miembros asignados.</div><?php endif;?><?php foreach($members as$m):?><div class="pm-member-row"><?=user_avatar_html($m,'avatar')?> <span><strong><?=e($m['name'])?></strong><small><?=e($m['role_name']?:'Miembro')?> · <?=(int)$m['allocation_percent']?>%</small></span></div><?php endforeach;?></div></section></aside></div>
<section class="panel"><div class="panel-header"><div><h2>Próximas tareas</h2><span class="table-sub">Trabajo pendiente, prioridad, horas y entrega.</span></div><a class="btn btn-light btn-small" href="project_kanban.php?project_id=<?=$id?>">Abrir Kanban</a></div><div class="table-wrap"><table><thead><tr><th>Tarea</th><th>Estado</th><th>Responsable</th><th>Prioridad</th><th>Horas</th><th>Entrega</th></tr></thead><tbody><?php if(!$tasks):?><tr><td colspan="6" class="empty">Sin tareas registradas.</td></tr><?php endif;?><?php foreach($tasks as$t):?><tr><td><a class="table-title" href="project_task_form.php?id=<?=$t['id']?>"><?=e($t['title'])?></a><small class="table-sub"><?=e($t['milestone_name']?:'Sin hito')?></small></td><td><?=pm_badge($t['status'],'task')?></td><td><?=e($t['assigned_name']?:'Sin asignar')?></td><td><?=pm_badge($t['priority'],'priority')?></td><td><?=e(number_format((float)$t['actual_hours'],1,',','.'))?> / <?=e(number_format((float)$t['planned_hours'],1,',','.'))?></td><td><?=e(pm_date($t['due_date']))?></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><div class="panel-header"><div><h2>Archivos del proyecto</h2><span class="table-sub">Briefs, contratos, diseños, hojas de cálculo, entregables y documentación.</span></div></div><div class="panel-body"><?php if(has_permission('projects.manage')):?><form method="post" action="project_file_action.php" enctype="multipart/form-data" class="inline-form"><?=csrf_field()?><input type="hidden" name="action" value="upload"><input type="hidden" name="project_id" value="<?=$id?>"><input type="file" name="file" required><button class="btn btn-secondary btn-small">SUBIR ARCHIVO</button></form><?php endif;?><div class="pm-files"><?php if(!$files):?><div class="empty">No hay archivos cargados.</div><?php endif;?><?php foreach($files as$f):?><div class="metric-row"><span><?=crm_icon('contract')?> <a class="table-title" href="project_file_action.php?action=download&id=<?=$f['id']?>"><?=e($f['file_name'])?></a><small class="table-sub"><?=e($f['user_name']?:'Usuario')?> · <?=e(number_format((int)$f['file_size']/1024,1,',','.'))?> KB · <?=e(date('d/m/Y H:i',strtotime($f['created_at'])))?></small></span><?php if(has_permission('projects.manage')):?><form method="post" action="project_file_action.php" onsubmit="return confirm('¿Eliminar archivo?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="project_id" value="<?=$id?>"><input type="hidden" name="id" value="<?=$f['id']?>"><button class="btn btn-light btn-small">Eliminar</button></form><?php endif;?></div><?php endforeach;?></div></div></section>
<?php if(has_permission('documents.view'))echo dms_related_panel('project',$id);?><?php require __DIR__.'/includes/footer.php';?>
